create schema butterflii;
revoke all on schema butterflii from public, anon, authenticated;
create table butterflii.members (user_id uuid primary key references auth.users(id) on delete cascade, role text not null check(role in ('parent','artist')));
create table butterflii.products (id uuid primary key default gen_random_uuid(), slug text unique not null, name text not null, description text not null default '', kind text not null check(kind in ('artwork','merchandise')), medium text, image_path text, price_pence integer not null check(price_pence>0), status text not null default 'draft' check(status in ('draft','published','archived')), created_by uuid references auth.users(id), created_at timestamptz not null default now());
create table butterflii.inventory (id uuid primary key default gen_random_uuid(), product_id uuid not null references butterflii.products(id), sku text unique not null, variant text not null default 'default', stock integer not null default 0 check(stock>=0), reserved integer not null default 0 check(reserved>=0 and reserved<=stock), verified boolean not null default false, unique(product_id,variant));
create table butterflii.media (id uuid primary key default gen_random_uuid(), product_id uuid not null references butterflii.products(id), object_path text not null unique, kind text not null check(kind in ('image','video')), approved boolean not null default false);
create table butterflii.orders (id uuid primary key default gen_random_uuid(), status text not null default 'pending' check(status in ('pending','paid','expired','cancelled','refunded')), stripe_session_id text unique, total_pence integer not null check(total_pence>=0), shipping_pence integer not null default 0 check(shipping_pence>=0), customer_email text, shipping_address jsonb, expires_at timestamptz, created_at timestamptz not null default now());
create table butterflii.order_items (order_id uuid references butterflii.orders(id), inventory_id uuid references butterflii.inventory(id), name text not null, quantity integer not null check(quantity>0), unit_pence integer not null check(unit_pence>0), primary key(order_id,inventory_id));
create table butterflii.deliveries (order_id uuid primary key references butterflii.orders(id), courier text, tracking_reference text, dispatched_at timestamptz);
create table butterflii.notifications (id uuid primary key default gen_random_uuid(), recipient uuid not null references butterflii.members(user_id), message text not null, created_at timestamptz not null default now(), read_at timestamptz);
create table butterflii.payment_events (event_id text primary key, processed_at timestamptz not null default now());
do $$ declare t text; begin foreach t in array array['members','products','inventory','media','orders','order_items','deliveries','notifications','payment_events'] loop execute format('alter table butterflii.%I enable row level security',t); end loop; end $$;
revoke all on all tables in schema butterflii from public, anon, authenticated;